app.use((req: Request, res: Response, next: NextFunction) => {
  const sessionId = req.headers['x-session-id'] as string;
  if (sessionId && !req.session.userId) {
    sessionStore.get(sessionId, (err, session) => {
      if (!err && session && (session as any).userId) {
        req.session.userId = (session as any).userId;
        // Save so the session persists for subsequent requests
        req.session.save((saveErr) => {
          if (saveErr) console.error('[SESSION] Error saving:', saveErr);
          next();
        });
      } else {
        next();
      }
    });
  } else {
    next();
  }
});

