     6→  user: User | null;
     7→  isLoading: boolean;
     8→  login: (email: string, password: string) => Promise<void>;
     9→  logout: () => void;
    10→  switchUser: (userId: string) => Promise<void>;
    11→}
    12→
    13→const AuthContext = createContext<AuthContextType | undefined>(undefined);
    14→
    15→export function AuthProvider({ children }: { children: React.ReactNode }) {
    16→  const [user, setUser] = useState<User | null>(null);
    17→  const [isLoading, setIsLoading] = useState(true);
    18→
    19→  const getSessionHeaders = (): Record<string, string> => {
    20→    const sessionId = localStorage.getItem("sessionId");
    21→    return sessionId ? { "X-Session-ID": sessionId } : {};
    22→  };
    23→
    24→  useEffect(() => {
    25→    // Проверяем сохранённую сессию при загрузке
    26→    const checkSession = async () => {
    27→      try {
    28→        const res = await fetch("/api/auth/session", {
    29→          headers: getSessionHeaders(),
    30→          credentials: "include",
    31→        });
    32→        if (res.ok) {
    33→          const data = await res.json();
    34→          setUser(data);
    35→        }
    36→      } catch (error) {
    37→        console.error("Failed to check session:", error);
    38→      } finally {
    39→        setIsLoading(false);
    40→      }
    41→    };
    42→
    43→    checkSession();
    44→  }, []);
    45→
    46→  const login = async (email: string, password: string) => {
    47→    setIsLoading(true);
    48→    try {
    49→      const res = await fetch("/api/auth/login", {
    50→        method: "POST",
    51→        headers: { "Content-Type": "application/json" },
    52→        body: JSON.stringify({ email, password }),
    53→        credentials: "include",
    54→      });
    55→
    56→      if (!res.ok) {
    57→        const errorData = await res.json();
    58→        throw new Error(errorData.error || "Ошибка входа. Проверьте email и пароль.");
    59→      }
    60→
    61→      const data = await res.json();
    62→      // Store sessionId for environments where cookies are blocked (iframe)
    63→      if (data.sessionId) {
    64→        localStorage.setItem("sessionId", data.sessionId);
    65→      }
    66→      // Clear all cached data so the new user gets their own fresh scope
    67→      queryClient.clear();
    68→      setUser(data);
    69→    } catch (error: any) {
    70→      throw new Error(error.message || "Ошибка входа. Проверьте email и пароль.");
    71→    } finally {
    72→      setIsLoading(false);
    73→    }
    74→  };
    75→
    76→  const logout = async () => {
    77→    try {
    78→      await fetch("/api/auth/logout", {
    79→        method: "POST",
    80→        headers: getSessionHeaders(),
    81→        credentials: "include",
    82→      });
    83→    } catch (error) {
    84→      console.error("Logout error:", error);
    85→    } finally {
    86→      localStorage.removeItem("sessionId");
    87→      queryClient.clear();
    88→      setUser(null);
    89→    }
    90→  };
    91→
    92→  const switchUser = async (userId: string) => {
    93→    setIsLoading(true);
    94→    try {
    95→      const res = await fetch("/api/auth/switch-user", {
    96→        method: "POST",
    97→        headers: { ...getSessionHeaders(), "Content-Type": "application/json" },
    98→        body: JSON.stringify({ userId }),
    99→        credentials: "include",
   100→      });
   101→
   102→      if (!res.ok) {
   103→        const errorData = await res.json();
   104→        throw new Error(errorData.error || "Ошибка переключения пользователя");
   105→      }
   106→
   107→      const data = await res.json();
   108→      if (data.sessionId) {
   109→        localStorage.setItem("sessionId", data.sessionId);
   110→      }
   111→      // Clear all cached data so the switched user gets their own fresh scope
   112→      queryClient.clear();
   113→      setUser(data);
   114→    } catch (error: any) {
   115→      throw new Error(error.message || "Ошибка переключения пользователя");
   116→    } finally {
   117→      setIsLoading(false);
   118→    }
   119→  };
   120→
   121→  return (
   122→    <AuthContext.Provider value={{ user, isLoading, login, logout, switchUser }}>
   123→      {children}
   124→    </AuthContext.Provider>
   125→  );
   126→}
   127→
   128→export function useAuth() {
   129→  const context = useContext(AuthContext);
   130→  if (!context) {
   131→    throw new Error("useAuth must be used within AuthProvider");
   132→  }
   133→  return context;
   134→}
